options.customCss:
:root {
  /* Paleta */
  --chat--color--primary: #00a884;
  --chat--color--primary-shade-50: #008f72;
  --chat--color--primary--shade-100: #00745e;
  --chat--color--secondary: #25d366;
  --chat--color-secondary-shade-50: #1fba59;
  --chat--color-white: #ffffff;
  --chat--color-light: #efeae2;
  --chat--color-light-shade-50: #d9d5ce;
  --chat--color-light-shade-100: #c7c2ba;
  --chat--color-medium: #8696a0;
  --chat--color-dark: #111b21;
  --chat--color-disabled: #c7c2ba;
  --chat--color-typing: #667781;

  /* Estrutura */
  --chat--spacing: 1rem;
  --chat--border-radius: 8px;
  --chat--transition-duration: 0.2s;
  --chat--font-family: Inter, ui-sans-serif, system-ui, -apple-system,
    BlinkMacSystemFont, "Segoe UI", sans-serif;

  /* Janela */
  --chat--window--width: 420px;
  --chat--window--height: min(680px, calc(100vh - 2rem));
  --chat--window--bottom: 1rem;
  --chat--window--right: 1rem;
  --chat--window--z-index: 9999;
  --chat--window--border: 1px solid #d7dfe3;
  --chat--window--border-radius: 12px;
  --chat--window--margin-bottom: 1rem;

  /* Cabecalho */
  --chat--header-height: auto;
  --chat--header--padding: 1rem 1.15rem 1rem 4.25rem;
  --chat--header--background: #008069;
  --chat--header--color: #ffffff;
  --chat--header--border-top: none;
  --chat--header--border-bottom: 1px solid #087866;
  --chat--header--border-left: none;
  --chat--header--border-right: none;
  --chat--heading--font-size: 1.15rem;
  --chat--subtitle--font-size: 0.85rem;
  --chat--subtitle--line-height: 1.45;

  /* Mensagens */
  --chat--message--font-size: 0.95rem;
  --chat--message--padding: 0.75rem 0.9rem;
  --chat--message--border-radius: 8px;
  --chat--message-line-height: 1.55;
  --chat--message--margin-bottom: 0.75rem;
  --chat--message--bot--background: #ffffff;
  --chat--message--bot--color: #111b21;
  --chat--message--bot--border: 1px solid rgba(17, 27, 33, 0.04);
  --chat--message--user--background: #d9fdd3;
  --chat--message--user--color: #111b21;
  --chat--message--user--border: 1px solid rgba(17, 27, 33, 0.04);
  --chat--message--pre--background: #f0f2f5;
  --chat--messages-list--padding: 1.15rem;

  /* Botao flutuante */
  --chat--toggle--size: 58px;
  --chat--toggle--width: var(--chat--toggle--size);
  --chat--toggle--height: var(--chat--toggle--size);
  --chat--toggle--border-radius: 50%;
  --chat--toggle--background: #25d366;
  --chat--toggle--hover--background: #1fba59;
  --chat--toggle--active--background: #169c49;
  --chat--toggle--color: #ffffff;

  /* Campo de mensagem */
  --chat--textarea--height: 56px;
  --chat--textarea--max-height: 160px;
  --chat--input--font-size: 0.95rem;
  --chat--input--border: 1px solid transparent;
  --chat--input--border-radius: 24px;
  --chat--input--padding: 0.8rem 0.9rem;
  --chat--input--background: #ffffff;
  --chat--input--text-color: #111b21;
  --chat--input--line-height: 1.45;
  --chat--input--placeholder--font-size: 0.9rem;
  --chat--input--border-active: 1px solid transparent;
  --chat--input--left--panel--width: 2.5rem;

  /* Botoes */
  --chat--button--padding: 0.65rem 1rem;
  --chat--button--border-radius: 6px;
  --chat--button--font-size: 0.9rem;
  --chat--button--line-height: 1.2;
  --chat--button--color--primary: #ffffff;
  --chat--button--background--primary: #00a884;
  --chat--button--border--primary: 1px solid #00a884;
  --chat--button--color--primary--hover: #ffffff;
  --chat--button--background--primary--hover: #008f72;
  --chat--button--border--primary--hover: 1px solid #008f72;
  --chat--button--color--primary--disabled: #64748b;
  --chat--button--background--primary--disabled: #e2e8f0;
  --chat--button--border--primary--disabled: 1px solid #e2e8f0;
  --chat--button--color--secondary: #334155;
  --chat--button--background--secondary: #ffffff;
  --chat--button--border--secondary: 1px solid #cbd5e1;
  --chat--button--color--secondary--hover: #0f172a;
  --chat--button--background--secondary--hover: #f1f5f9;
  --chat--button--border--secondary--hover: 1px solid #94a3b8;
  --chat--button--color--secondary--disabled: #94a3b8;
  --chat--button--background--secondary--disabled: #f8fafc;
  --chat--button--border--secondary--disabled: 1px solid #e2e8f0;
  --chat--close--button--color-hover: #bfdbfe;

  /* Envio e anexo */
  --chat--input--send--button--background: transparent;
  --chat--input--send--button--color: #00a884;
  --chat--input--send--button--background-hover: #e7f8f3;
  --chat--input--send--button--color-hover: #008069;
  --chat--input--file--button--background: transparent;
  --chat--input--file--button--color: #64748b;
  --chat--input--file--button--background-hover: #f1f5f9;
  --chat--input--file--button--color-hover: #008069;
  --chat--files-spacing: 0.35rem;

  /* Corpo e rodape */
  --chat--body--background: #efeae2;
  --chat--footer--background: #f0f2f5;
  --chat--footer--color: #667781;
}

/* Janela principal */
.chat-window {
  overflow: hidden;
  box-shadow:
    0 24px 64px rgba(17, 27, 33, 0.22),
    0 6px 18px rgba(17, 27, 33, 0.12);
  animation: chat-window-in 0.35s cubic-bezier(0.22, 1, 0.36, 1);
}

/* Cabecalho */
.chat-header {
  position: relative;
}

.chat-header::before {
  position: absolute;
  top: 50%;
  left: 1rem;
  width: 42px;
  height: 42px;
  content: "";
  background: #d9fdd3;
  border: 2px solid rgba(255, 255, 255, 0.72);
  border-radius: 50%;
  box-shadow: 0 2px 8px rgba(17, 27, 33, 0.2);
  transform: translateY(-50%);
}

.chat-header::after {
  position: absolute;
  top: calc(50% + 10px);
  left: 2.9rem;
  width: 10px;
  height: 10px;
  content: "";
  background: #25d366;
  border: 2px solid #008069;
  border-radius: 50%;
}

.chat-heading {
  margin: 0;
  font-weight: 700;
  letter-spacing: 0;
}

.chat-header p {
  margin: 0.3rem 0 0;
  color: #d9fdd3;
}

/* Area de conversa */
.chat-messages-list {
  position: relative;
  scrollbar-color: rgba(134, 150, 160, 0.55) transparent;
  scrollbar-width: thin;
  background-color: #efeae2;
  background-image:
    radial-gradient(circle at 20px 20px, rgba(17, 27, 33, 0.035) 1.5px, transparent 1.6px),
    radial-gradient(circle at 45px 45px, rgba(0, 128, 105, 0.035) 1.5px, transparent 1.6px);
  background-size: 64px 64px;
}

.chat-message {
  position: relative;
  max-width: 82%;
  overflow-wrap: anywhere;
  box-shadow: 0 1px 2px rgba(17, 27, 33, 0.12);
  animation: chat-message-in 0.28s cubic-bezier(0.22, 1, 0.36, 1) both;
}

.chat-message-from-user {
  margin-left: auto;
  border-top-right-radius: 2px;
  transform-origin: right bottom;
}

.chat-message-from-bot {
  margin-right: auto;
  border-top-left-radius: 2px;
  transform-origin: left bottom;
}

.chat-message-from-user::after,
.chat-message-from-bot::before {
  position: absolute;
  top: -1px;
  width: 0;
  height: 0;
  content: "";
  border-style: solid;
}

.chat-message-from-user::after {
  right: -8px;
  border-width: 0 0 10px 10px;
  border-color: transparent transparent transparent #d9fdd3;
}

.chat-message-from-bot::before {
  left: -8px;
  border-width: 0 10px 10px 0;
  border-color: transparent #ffffff transparent transparent;
}

.chat-message p {
  margin: 0 0 0.55rem;
}

.chat-message p:last-child {
  margin-bottom: 0;
}

.chat-message a {
  color: inherit;
  font-weight: 600;
  text-decoration: underline;
  text-underline-offset: 2px;
}

.chat-message pre,
.chat-message code {
  font-family: "Cascadia Code", "SFMono-Regular", Consolas, monospace;
}

.chat-message pre {
  max-width: 100%;
  padding: 0.75rem;
  overflow-x: auto;
  border: 1px solid #e2e8f0;
  border-radius: 6px;
}

/* Entrada de texto */
.chat-input {
  gap: 0.5rem;
  padding: 0.85rem;
  background: #f0f2f5;
  border-top: 1px solid #e1e6e8;
}

.chat-input textarea {
  resize: none;
  transition:
    border-color var(--chat--transition-duration),
    box-shadow var(--chat--transition-duration);
}

.chat-input textarea:focus {
  outline: none;
  box-shadow: 0 0 0 3px rgba(0, 168, 132, 0.14);
}

.chat-input textarea::placeholder {
  color: #94a3b8;
}

.chat-input button {
  transition:
    color var(--chat--transition-duration),
    background-color var(--chat--transition-duration),
    transform var(--chat--transition-duration);
}

.chat-input button:active {
  transform: scale(0.94);
}

.chat-input-send-button {
  border-radius: 50%;
}

.chat-input-send-button:hover {
  transform: rotate(-8deg) scale(1.08);
}

/* Botao que abre o chat */
.chat-window-toggle {
  border: 1px solid rgba(255, 255, 255, 0.22);
  box-shadow:
    0 12px 28px rgba(37, 211, 102, 0.34),
    0 4px 10px rgba(17, 27, 33, 0.18);
  transition:
    background-color var(--chat--transition-duration),
    box-shadow var(--chat--transition-duration),
    transform var(--chat--transition-duration);
  animation: chat-toggle-pulse 2.8s ease-in-out infinite;
}

.chat-window-toggle:hover {
  box-shadow:
    0 16px 34px rgba(37, 211, 102, 0.42),
    0 5px 12px rgba(17, 27, 33, 0.18);
  transform: translateY(-3px) scale(1.04);
}

.chat-window-toggle:active {
  transform: translateY(0) scale(0.97);
}

/* Acessibilidade */
.chat-window button:focus-visible,
.chat-window a:focus-visible,
.chat-window textarea:focus-visible,
.chat-window-toggle:focus-visible {
  outline: 3px solid rgba(0, 168, 132, 0.35);
  outline-offset: 2px;
}

@keyframes chat-window-in {
  from {
    opacity: 0;
    transform: translateY(18px) scale(0.96);
  }

  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

@keyframes chat-message-in {
  from {
    opacity: 0;
    transform: translateY(8px) scale(0.97);
  }

  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

@keyframes chat-toggle-pulse {
  0%,
  100% {
    box-shadow:
      0 12px 28px rgba(37, 211, 102, 0.3),
      0 0 0 0 rgba(37, 211, 102, 0.22);
  }

  50% {
    box-shadow:
      0 14px 32px rgba(37, 211, 102, 0.38),
      0 0 0 10px rgba(37, 211, 102, 0);
  }
}

/* Celulares */
@media (max-width: 520px) {
  :root {
    --chat--window--width: calc(100vw - 1rem);
    --chat--window--height: calc(100dvh - 1rem);
    --chat--window--right: 0.5rem;
    --chat--window--bottom: 0.5rem;
    --chat--window--border-radius: 8px;
    --chat--messages-list--padding: 0.85rem;
    --chat--header--padding: 1rem;
  }

  .chat-message {
    max-width: 88%;
  }
}

@media (prefers-reduced-motion: reduce) {
  .chat-window *,
  .chat-window-toggle {
    scroll-behavior: auto !important;
    transition-duration: 0.01ms !important;
  }
}

/* Modo pagina inteira do n8n Chat */
.chat-layout {
  min-height: 100dvh;
  background: #efeae2;
}

.chat-layout .chat-header {
  min-height: 92px;
  padding: 1rem clamp(1rem, 4vw, 3rem) 1rem 5rem;
  display: flex;
  flex-direction: column;
  justify-content: center;
  box-sizing: border-box;
  box-shadow: 0 2px 10px rgba(17, 27, 33, 0.16);
  z-index: 2;
}

.chat-layout .chat-header::before {
  left: clamp(1rem, 2.25vw, 2rem);
  width: 44px;
  height: 44px;
}

.chat-layout .chat-header::after {
  top: calc(50% + 11px);
  left: calc(clamp(1rem, 2.25vw, 2rem) + 33px);
}

.chat-layout .chat-heading {
  font-size: 1.2rem;
  line-height: 1.25;
}

.chat-layout .chat-header p {
  margin-top: 0.2rem;
  font-size: 0.78rem;
  line-height: 1.3;
}

.chat-layout .chat-body {
  min-height: 0;
  background:
    linear-gradient(rgba(239, 234, 226, 0.88), rgba(239, 234, 226, 0.88)),
    radial-gradient(circle at 24px 24px, rgba(17, 27, 33, 0.065) 1.2px, transparent 1.3px);
  background-size: auto, 56px 56px;
}

.chat-layout .chat-messages-list {
  width: 100%;
  padding: 1.5rem max(1rem, calc((100% - 1120px) / 2));
  box-sizing: border-box;
  background: transparent;
}

.chat-layout .chat-message {
  width: fit-content;
  max-width: min(78%, 820px);
  margin-bottom: 0.65rem;
  padding: 0.7rem 0.85rem;
  border: 0;
  font-size: 0.95rem;
  line-height: 1.5;
}

.chat-layout .chat-message-from-bot {
  margin-right: auto;
}

.chat-layout .chat-message-from-user {
  margin-left: auto;
}

.chat-layout .chat-message ul,
.chat-layout .chat-message ol {
  margin: 0.6rem 0 0.2rem;
  padding-left: 1.25rem;
}

.chat-layout .chat-message li {
  margin: 0.18rem 0;
}

.chat-layout .chat-message h1,
.chat-layout .chat-message h2,
.chat-layout .chat-message h3,
.chat-layout .chat-message h4 {
  margin: 0 0 0.55rem;
  font-size: 1rem;
  line-height: 1.35;
}

.chat-layout .chat-message pre {
  margin: 0.65rem 0 0;
  background: #f6f7f8;
  border-color: #dde3e6;
}

/* Estado de digitacao compacto */
.chat-layout .chat-message-typing {
  width: 64px;
  min-height: 36px;
  padding: 0.65rem 0.8rem;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
}

.chat-layout .chat-message-typing span {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #667781;
  animation: chat-typing-dot 1.2s ease-in-out infinite;
}

.chat-layout .chat-message-typing span:nth-child(2) {
  animation-delay: 0.15s;
}

.chat-layout .chat-message-typing span:nth-child(3) {
  animation-delay: 0.3s;
}

/* Composer */
.chat-layout .chat-input {
  width: 100%;
  min-height: 72px;
  padding: 0.65rem max(1rem, calc((100% - 1120px) / 2));
  display: flex;
  align-items: center;
  box-sizing: border-box;
  background: #f0f2f5;
  border-top: 1px solid #d8dfe3;
  box-shadow: 0 -3px 14px rgba(17, 27, 33, 0.06);
}

.chat-layout .chat-inputs {
  width: 100%;
  min-width: 0;
  min-height: 48px;
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.chat-layout .chat-input textarea {
  min-height: 48px;
  max-height: 128px;
  padding: 0.78rem 1rem;
  box-sizing: border-box;
  border: 1px solid #ffffff;
  border-radius: 24px;
  box-shadow: 0 1px 2px rgba(17, 27, 33, 0.08);
}

.chat-layout .chat-input textarea:focus {
  border-color: #b8e4da;
  box-shadow:
    0 0 0 3px rgba(0, 168, 132, 0.12),
    0 1px 2px rgba(17, 27, 33, 0.08);
}

.chat-layout .chat-input-send-button {
  width: 44px;
  min-width: 44px;
  height: 44px;
  padding: 0;
  display: grid;
  place-items: center;
  color: #ffffff;
  background: #00a884;
  border: 0;
  border-radius: 50%;
  box-shadow: 0 4px 10px rgba(0, 128, 105, 0.22);
}

.chat-layout .chat-input-send-button:hover {
  color: #ffffff;
  background: #008f72;
  transform: translateY(-1px);
}

.chat-layout .chat-input-send-button:disabled {
  color: #ffffff;
  background: #aebac1;
  box-shadow: none;
  cursor: not-allowed;
}

@keyframes chat-typing-dot {
  0%,
  60%,
  100% {
    opacity: 0.45;
    transform: translateY(0);
  }

  30% {
    opacity: 1;
    transform: translateY(-3px);
  }
}

@media (max-width: 720px) {
  .chat-layout .chat-header {
    min-height: 76px;
    padding: 0.75rem 3.5rem 0.75rem 4.25rem;
  }

  .chat-layout .chat-header::before {
    left: 0.9rem;
    width: 38px;
    height: 38px;
  }

  .chat-layout .chat-header::after {
    top: calc(50% + 9px);
    left: 2.65rem;
    width: 9px;
    height: 9px;
  }

  .chat-layout .chat-heading {
    font-size: 1rem;
  }

  .chat-layout .chat-messages-list {
    padding: 1rem 0.75rem;
  }

  .chat-layout .chat-message {
    max-width: 88%;
    font-size: 0.92rem;
  }

  .chat-layout .chat-input {
    min-height: 66px;
    padding: 0.55rem 0.65rem;
  }

  .chat-layout .chat-input-send-button {
    width: 42px;
    min-width: 42px;
    height: 42px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .chat-layout .chat-message-typing span {
    animation: none;
  }
}
